WFJ.Data.add("book", {
  ["6993fb795753d887"] = { "I calderoni, protetti dai fedeli seguaci del culto, avrebbero poi agito come generatori di pestilenza, diffondendo il morbo nelle ignare campagne e città del nord di Lordaeron.\n\nIl piano del Re dei Lich funzionò alla perfezione. Molti dei villaggi settentrionali di Lordaeron furono contaminati quasi subito. Proprio come in Nordania, i cittadini che contraevano la pestilenza morivano e risorgevano come schiavi devoti del Re dei Lich.", "." },
  ["69ac9f300615e1af"] = { "Il Custode mi ha passato la lettera che hai scoperto, {name}, e ho pensato che ti avrebbe fatto piacere un aggiornamento.\n\nL'ultimo familiare in vita del \"Vargus\" menzionato è stato rintracciato nel deserto di ⟦Silithus=Silitus⟧, alla ⟦Cenarion Hold=Fortezza Cenariana⟧. Si fa chiamare Garon Hutchins.\n\nDovresti parlargli durante la tua prossima spedizione in quelle terre desolate. Potrebbe voler sapere ciò che abbiamo scoperto.", "." },
  ["69def289e1549646"] = { "Corni Carbonizzati:\n\nCome le zanne di ragno bruciate, i corni carbonizzati delle chimere che vivono nella ⟦Charred Vale=Valle Bruciata⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ su Kalimdor, possiedono una qualità molto apprezzata.\n\nAppiattiti a colpi di martello e trattati a dovere, diventano estremamente resistenti alle sollecitazioni fisiche.", "." },
